// See https://www.iana.org/assignments/tls-parameters/tls-parameters.xhtml#tls-signaturescheme
// This contains signature schemes supported by Chrome.
const SignatureSchemeStrings = new Map([
  // The full name for these schemes is RSASSA-PKCS1-v1_5, sometimes
  // "PKCS#1 v1.5", but those are very long, so let "RSA" vs "RSA-PSS"
  // disambiguate.
  [0x0201, 'RSA with SHA-1'],
  [0x0401, 'RSA with SHA-256'],
  [0x0501, 'RSA with SHA-384'],
  [0x0601, 'RSA with SHA-512'],

  // We omit the curve from these names because in TLS 1.2 these code points
  // were not specific to a curve. Saying "P-256" for a server that used a P-384
  // key with SHA-256 in TLS 1.2 would be confusing.
  [0x0403, 'ECDSA with SHA-256'],
  [0x0503, 'ECDSA with SHA-384'],

  [0x0804, 'RSA-PSS with SHA-256'],
  [0x0805, 'RSA-PSS with SHA-384'],
  [0x0806, 'RSA-PSS with SHA-512'],
]);

const LOCK_ICON_NAME = 'lock';
const WARNING_ICON_NAME = 'warning';
const UNKNOWN_ICON_NAME = 'indeterminate-question-box';

function getSecurityStateIconNameForDetailedView(securityState: Protocol.Security.SecurityState): string {
  let iconName: string;

  switch (securityState) {
    case Protocol.Security.SecurityState.Neutral:   // fallthrough
    case Protocol.Security.SecurityState.Insecure:  // fallthrough
    case Protocol.Security.SecurityState.InsecureBroken:
      iconName = WARNING_ICON_NAME;
      break;
    case Protocol.Security.SecurityState.Secure:
      iconName = LOCK_ICON_NAME;
      break;
    case Protocol.Security.SecurityState.Info:  // fallthrough
    case Protocol.Security.SecurityState.Unknown:
      iconName = UNKNOWN_ICON_NAME;
      break;
  }

  return iconName;
}

export function getSecurityStateIconForDetailedView(securityState: Protocol.Security.SecurityState,
                                                    className: string): TemplateResult {
  return html`<devtools-icon name=${getSecurityStateIconNameForDetailedView(securityState)} class=${
      className}></devtools-icon>`;
}

export function getSecurityStateIconForOverview(securityState: Protocol.Security.SecurityState, className: string,
                                                title?: string): TemplateResult {
  let iconName: string;
  switch (securityState) {
    case Protocol.Security.SecurityState.Unknown:  // fallthrough
    case Protocol.Security.SecurityState.Neutral:
      iconName = UNKNOWN_ICON_NAME;
      break;
    case Protocol.Security.SecurityState.Insecure:  // fallthrough
    case Protocol.Security.SecurityState.InsecureBroken:
      iconName = WARNING_ICON_NAME;
      break;
    case Protocol.Security.SecurityState.Secure:
      iconName = LOCK_ICON_NAME;
      break;
    case Protocol.Security.SecurityState.Info:
      throw new Error(`Unexpected security state ${securityState}`);
  }
  return html`<devtools-icon name=${iconName} class=${className} title=${ifDefined(title)}></devtools-icon>`;
}

export function renderHighlightedUrl(url: Platform.DevToolsPath.UrlString, securityState: string): TemplateResult {
  const schemeSeparator = '://';
  const index = url.indexOf(schemeSeparator);

  // If the separator is not found, just display the text without highlighting.
  if (index === -1) {
    return html`<span>${url}</span>`;
  }

  const scheme = url.substr(0, index);
  const content = url.substr(index + schemeSeparator.length);

  return html`
    <span class="highlighted-url">
      <span class=${`url-scheme-${securityState}`}>${scheme}</span>
      <span class="url-scheme-separator">${schemeSeparator}</span>
      <span>${content}</span>
    </span>`;
}

export function renderCertificateViewerButton(text: string, jslogContext: string, onClick: () => void): TemplateResult {
  return html`
    <devtools-button
        class="origin-button"
        title=${text}
        .variant=${Buttons.Button.Variant.OUTLINED}
        .jslogContext=${jslogContext}
        @click=${(e: Event) => {
    e.consume();
    onClick();
  }}>${text}</devtools-button>`;
}

export interface ViewInput {
  mainOrigin: string|null;
  sidebarOrigins: ReadonlyMap<Platform.DevToolsPath.UrlString, Protocol.Security.SecurityState>;
  originsHidden: boolean;
  showOriginsUnconditionally: boolean;
  overviewSecurityState: Protocol.Security.SecurityState;
  activeOrigin: Platform.DevToolsPath.UrlString|null;
  activeOriginState: OriginState|null;
  visibleSecurityState: PageVisibleSecurityState|null;
  filterRequestCounts: ReadonlyMap<string, number>;
  onShowOrigin: (origin: Platform.DevToolsPath.UrlString|null) => void;
}

export type View = (input: ViewInput, output: undefined, target: HTMLElement) => void;

export const DEFAULT_VIEW: View = (input, _output, target): void => {
  const {activeOrigin, activeOriginState} = input;
  // clang-format off
  render(html`
    <devtools-split-view direction="column" name="security">
      <devtools-widget
        slot="sidebar"
        autofocus
        class="panel-sidebar"
        jslog=${VisualLogging.pane('sidebar').track({resize: true})}
        ${widget(SecurityPanelSidebar, {
          mainOrigin: input.mainOrigin,
          origins: input.sidebarOrigins,
          originsHidden: input.originsHidden,
          showOriginsUnconditionally: input.showOriginsUnconditionally,
          overviewSecurityState: input.overviewSecurityState,
          activeOrigin: input.activeOrigin,
          onShowOrigin: input.onShowOrigin,
        })}>
      </devtools-widget>
      ${activeOrigin !== null && activeOriginState !== null ? html`
        <devtools-widget
          slot="main"
          ${widget(SecurityOriginView, {
            origin: activeOrigin,
            securityState: activeOriginState.securityState,
            securityDetails: activeOriginState.securityDetails,
            loadedFromCache: activeOriginState.loadedFromCache,
          })}>
        </devtools-widget>` : html`
        <devtools-widget
          slot="main"
          ${widget(SecurityMainView, {
            visibleSecurityState: input.visibleSecurityState,
            filterRequestCounts: input.filterRequestCounts,
          })}>
        </devtools-widget>`}
    </devtools-split-view>
  `, target);
  // clang-format on
};

export class SecurityPanel extends UI.Panel.Panel implements SDK.TargetManager.SDKModelObserver<SecurityModel> {
  readonly #view: View;
  readonly #lastResponseReceivedForLoaderId = new Map<string, SDK.NetworkRequest.NetworkRequest>();
  readonly #origins = new Map<Platform.DevToolsPath.UrlString, OriginState>();
  #sidebarOrigins: ReadonlyMap<Platform.DevToolsPath.UrlString, Protocol.Security.SecurityState> = new Map();
  #filterRequestCounts: ReadonlyMap<string, number> = new Map();
  #visibleSecurityState: PageVisibleSecurityState|null = null;
  #activeOrigin: Platform.DevToolsPath.UrlString|null = null;
  #mainOrigin: string|null = null;
  #originsHidden = false;
  #showOriginsUnconditionally = false;
  #overviewSecurityState: Protocol.Security.SecurityState = Protocol.Security.SecurityState.Unknown;
  #eventListeners: Common.EventTarget.EventDescriptor[] = [];
  #securityModel: SecurityModel|null = null;

  readonly #onShowOrigin = (origin: Platform.DevToolsPath.UrlString|null): void => {
    this.showOrigin(origin);
  };

  constructor(view: View = DEFAULT_VIEW) {
    super('security');
    this.#view = view;

    SDK.TargetManager.TargetManager.instance().observeModels(SecurityModel, this, {scoped: true});
    SDK.TargetManager.TargetManager.instance().addModelListener(SDK.ResourceTreeModel.ResourceTreeModel,
                                                                SDK.ResourceTreeModel.Events.PrimaryPageChanged,
                                                                this.#onPrimaryPageChanged, this);
  }

  static instance(opts: {forceNew: boolean|null} = {forceNew: null}): SecurityPanel {
    const {forceNew} = opts;
    if (!securityPanelInstance || forceNew) {
      securityPanelInstance = new SecurityPanel();
    }

    return securityPanelInstance;
  }
  override wasShown(): void {
    super.wasShown();
    this.requestUpdate();
  }

  override performUpdate(): void {
    const activeOriginState = this.#activeOrigin ? this.#origins.get(this.#activeOrigin) ?? null : null;
    const input: ViewInput = {
      mainOrigin: this.#mainOrigin,
      sidebarOrigins: this.#sidebarOrigins,
      originsHidden: this.#originsHidden,
      showOriginsUnconditionally: this.#showOriginsUnconditionally,
      overviewSecurityState: this.#overviewSecurityState,
      activeOrigin: this.#activeOrigin,
      activeOriginState,
      visibleSecurityState: this.#visibleSecurityState,
      filterRequestCounts: this.#filterRequestCounts,
      onShowOrigin: this.#onShowOrigin,
    };
    this.#view(input, undefined, this.contentElement);
  }

  showOrigin(origin: Platform.DevToolsPath.UrlString|null): void {
    if (origin !== null && !this.#origins.has(origin)) {
      return;
    }
    if (this.#activeOrigin === origin) {
      return;
    }
    this.#activeOrigin = origin;
    this.requestUpdate();
  }

  #updateVisibleSecurityState(visibleSecurityState: PageVisibleSecurityState): void {
    this.#overviewSecurityState = visibleSecurityState.securityState;
    this.#visibleSecurityState = visibleSecurityState;
    this.requestUpdate();
  }

  #onVisibleSecurityStateChanged({data}: Common.EventTarget.EventTargetEvent<PageVisibleSecurityState>): void {
    this.#updateVisibleSecurityState(data);
  }

  #onResponseReceived(event: Common.EventTarget.EventTargetEvent<SDK.NetworkManager.ResponseReceivedEvent>): void {
    const request = event.data.request;
    if (request.resourceType() === Common.ResourceType.resourceTypes.Document && request.loaderId) {
      this.#lastResponseReceivedForLoaderId.set(request.loaderId, request);
    }
  }

  #processRequest(request: SDK.NetworkRequest.NetworkRequest): void {
    const origin = Common.ParsedURL.ParsedURL.extractOrigin(request.url());

    if (!origin) {
      // We don't handle resources like data: URIs. Most of them don't affect the lock icon.
      return;
    }

    let securityState = request.securityState();
    if (request.mixedContentType === Protocol.Security.MixedContentType.Blockable ||
        request.mixedContentType === Protocol.Security.MixedContentType.OptionallyBlockable) {
      securityState = Protocol.Security.SecurityState.Insecure;
    }

    const originState = this.#origins.get(origin);
    if (originState) {
      if (securityStateCompare(securityState, originState.securityState) < 0) {
        originState.securityState = securityState;
        const securityDetails = request.securityDetails();
        if (securityDetails) {
          originState.securityDetails = securityDetails;
        }
        const newSidebarOrigins = new Map(this.#sidebarOrigins);
        newSidebarOrigins.set(origin, securityState);
        this.#sidebarOrigins = newSidebarOrigins;
        this.requestUpdate();
      }
    } else {
      // This stores the first security details we see for an origin, but we should
      // eventually store a (deduplicated) list of all the different security
      // details we have seen. https://crbug.com/503170
      const newOriginState: OriginState = {
        securityState,
        securityDetails: request.securityDetails(),
        loadedFromCache: request.cached(),
      };
      this.#origins.set(origin, newOriginState);
      const newSidebarOrigins = new Map(this.#sidebarOrigins);
      newSidebarOrigins.set(origin, securityState);
      this.#sidebarOrigins = newSidebarOrigins;
      this.requestUpdate();
    }
  }

  #onRequestFinished(event: Common.EventTarget.EventTargetEvent<SDK.NetworkRequest.NetworkRequest>): void {
    const request = event.data;
    this.#updateFilterRequestCounts(request);
    this.#processRequest(request);
  }

  #updateFilterRequestCounts(request: SDK.NetworkRequest.NetworkRequest): void {
    if (request.mixedContentType === Protocol.Security.MixedContentType.None) {
      return;
    }

    let filterKey: string = NetworkForward.UIFilter.MixedContentFilterValues.ALL;
    if (request.wasBlocked()) {
      filterKey = NetworkForward.UIFilter.MixedContentFilterValues.BLOCKED;
    } else if (request.mixedContentType === Protocol.Security.MixedContentType.Blockable) {
      filterKey = NetworkForward.UIFilter.MixedContentFilterValues.BLOCK_OVERRIDDEN;
    } else if (request.mixedContentType === Protocol.Security.MixedContentType.OptionallyBlockable) {
      filterKey = NetworkForward.UIFilter.MixedContentFilterValues.DISPLAYED;
    }

    const currentCount = this.#filterRequestCounts.get(filterKey) ?? 0;
    const newCounts = new Map(this.#filterRequestCounts);
    newCounts.set(filterKey, currentCount + 1);
    this.#filterRequestCounts = newCounts;
    this.requestUpdate();
  }

  modelAdded(securityModel: SecurityModel): void {
    if (securityModel.target() !== securityModel.target().outermostTarget()) {
      return;
    }

    this.#securityModel = securityModel;
    const resourceTreeModel = securityModel.resourceTreeModel();
    const networkManager = securityModel.networkManager();
    if (this.#eventListeners.length) {
      Common.EventTarget.removeEventListeners(this.#eventListeners);
    }
    this.#eventListeners = [
      securityModel.addEventListener(Events.VisibleSecurityStateChanged, this.#onVisibleSecurityStateChanged, this),
      resourceTreeModel.addEventListener(SDK.ResourceTreeModel.Events.InterstitialShown, this.#onInterstitialShown,
                                         this),
      resourceTreeModel.addEventListener(SDK.ResourceTreeModel.Events.InterstitialHidden, this.#onInterstitialHidden,
                                         this),
      networkManager.addEventListener(SDK.NetworkManager.Events.ResponseReceived, this.#onResponseReceived, this),
      networkManager.addEventListener(SDK.NetworkManager.Events.RequestFinished, this.#onRequestFinished, this),
    ];

    if (resourceTreeModel.isInterstitialShowing) {
      this.#onInterstitialShown();
    }
  }

  modelRemoved(securityModel: SecurityModel): void {
    if (this.#securityModel !== securityModel) {
      return;
    }

    this.#securityModel = null;
    Common.EventTarget.removeEventListeners(this.#eventListeners);
  }

  #onPrimaryPageChanged(
      event: Common.EventTarget.EventTargetEvent<
          {frame: SDK.ResourceTreeModel.ResourceTreeFrame, type: SDK.ResourceTreeModel.PrimaryPageChangeType}>): void {
    const {frame} = event.data;
    const request = this.#lastResponseReceivedForLoaderId.get(frame.loaderId);

    this.#activeOrigin = null;
    this.#origins.clear();
    this.#sidebarOrigins = new Map();
    this.#lastResponseReceivedForLoaderId.clear();
    this.#filterRequestCounts = new Map();

    // If we could not find a matching request (as in the case of clicking
    // through an interstitial, see https://crbug.com/669309), set the origin
    // based upon the url data from the PrimaryPageChanged event itself.
    const origin = Common.ParsedURL.ParsedURL.extractOrigin(request ? request.url() : frame.url);
    this.#mainOrigin = origin;
    this.requestUpdate();

    if (request) {
      this.#processRequest(request);
    }
  }

  #onInterstitialShown(): void {
    // The panel might have been displaying the origin view on the
    // previously loaded page. When showing an interstitial, switch
    // back to the overview view.
    this.#activeOrigin = null;
    this.#originsHidden = true;
    this.#showOriginsUnconditionally = false;
    this.requestUpdate();
  }

  #onInterstitialHidden(): void {
    this.#originsHidden = false;
    this.#showOriginsUnconditionally = true;
    this.requestUpdate();
  }
}

export enum OriginGroup {
  /* eslint-disable @typescript-eslint/naming-convention -- Used by web_tests. */
  MainOrigin = 'MainOrigin',
  NonSecure = 'NonSecure',
  Secure = 'Secure',
  Unknown = 'Unknown',
  /* eslint-enable @typescript-eslint/naming-convention */
}

export interface SecurityMainViewExplanation {
  securityState: Protocol.Security.SecurityState;
  title?: string;
  summary: string;
  description: string;
  certificate: string[];
  recommendations?: string[];
  mixedContent?: {filterKey: string, count: number};
}

export interface SecurityMainViewInput {
  securityState: Protocol.Security.SecurityState|null;
  summaryText: string;
  mainExplanations: SecurityMainViewExplanation[];
  extraExplanations: SecurityMainViewExplanation[];
  onShowCertificateViewer: (certificate: string[]) => void;
  onShowNetworkFilter: (filterKey: string) => void;
}

export type SecurityMainViewFunction = (input: SecurityMainViewInput, _output: undefined, target: HTMLElement) => void;

function renderExplanation(explanation: SecurityMainViewExplanation, input: SecurityMainViewInput): TemplateResult {
  const icon = getSecurityStateIconForDetailedView(explanation.securityState,
                                                   `security-property security-property-${explanation.securityState}`);
  const mixedContent = explanation.mixedContent;
  return html`
    <div class=${`security-explanation security-explanation-${explanation.securityState}`}>
      ${icon}
      <div class="security-explanation-text">
        <div class="security-explanation-title">${
      explanation.title ? html`<span>${explanation.title} - </span><span class=${
                                                        `security-explanation-title-${explanation.securityState}`}>${
                              explanation.summary}</span>` :
                          explanation.summary}</div>
        <div>${explanation.description}</div>
        ${
      explanation.certificate.length > 0 ?
          renderCertificateViewerButton(i18nString(UIStrings.viewCertificate), 'security.view-certificate',
                                        () => input.onShowCertificateViewer(explanation.certificate)) :
          nothing}
        ${
      explanation.recommendations?.length ? html`
          <ul class="security-explanation-recommendations">
            ${explanation.recommendations.map(recommendation => html`<li>${recommendation}</li>`)}
          </ul>` :
                                            nothing}
        ${
      mixedContent ?
          (mixedContent.count === 0 ?
               html`
          <div class="security-mixed-content">${i18nString(UIStrings.reloadThePageToRecordRequestsFor)}</div>` :
               html`
          <devtools-button
              class="security-mixed-content"
              .variant=${Buttons.Button.Variant.TEXT}
              .jslogContext=${'reveal-in-network'}
              @click=${(e: Event) => {
                 e.consume();
                 input.onShowNetworkFilter(mixedContent.filterKey);
               }}>${i18nString(UIStrings.viewDRequestsInNetworkPanel, {n: mixedContent.count})}</devtools-button>`) :
          nothing}
      </div>
    </div>`;
}

export const DEFAULT_SECURITY_MAIN_VIEW: SecurityMainViewFunction = (input, _output, target): void => {
  const isInsecureBroken = input.securityState === Protocol.Security.SecurityState.InsecureBroken;
  const insecureIconClass = isInsecureBroken ? 'lock-icon lock-icon-insecure-broken' : 'lock-icon lock-icon-insecure';
  const insecureTooltip = isInsecureBroken ? i18nString(UIStrings.notSecureBroken) : i18nString(UIStrings.notSecure);

  // clang-format off
  render(
    html`
      <style>${lockIconStyles}</style>
      <style>${mainViewStyles}</style>
      <div class=${Directives.classMap({
        'security-summary': true,
        [`security-summary-${input.securityState}`]: input.securityState !== null,
      })}>
        <div class="security-summary-section-title" role="heading" aria-level="1">
          ${i18nString(UIStrings.securityOverview)}
        </div>
        <div class="lock-spectrum">
          ${getSecurityStateIconForOverview(
              Protocol.Security.SecurityState.Secure, 'lock-icon lock-icon-secure', i18nString(UIStrings.secure))}
          ${getSecurityStateIconForOverview(
              Protocol.Security.SecurityState.Neutral, 'lock-icon lock-icon-neutral', i18nString(UIStrings.info))}
          ${getSecurityStateIconForOverview(
              isInsecureBroken ? Protocol.Security.SecurityState.InsecureBroken : Protocol.Security.SecurityState.Insecure,
              insecureIconClass, insecureTooltip)}
        </div>
        <div class="triangle-pointer-container">
          <div class="triangle-pointer-wrapper">
            <div class="triangle-pointer"></div>
          </div>
        </div>
        <div class="security-summary-text" role="heading" aria-level="2">${input.summaryText}</div>
      </div>
      <div class="security-explanation-list security-explanations-main">${input.mainExplanations.length > 0 ? input.mainExplanations.map(explanation => renderExplanation(explanation, input)) : nothing}</div>
      <div class="security-explanation-list security-explanations-extra">${input.extraExplanations.length > 0 ? input.extraExplanations.map(explanation => renderExplanation(explanation, input)) : nothing}</div>
    `,
    target,
    {
      container: {
        classes: ['security-main-view'],
        attributes: {
          jslog: `${VisualLogging.pane('security.main-view')}`,
        },
      },
    },
  );
  // clang-format on
};

export class SecurityMainView extends UI.Widget.VBox {
  readonly #view: SecurityMainViewFunction;
  #visibleSecurityState: PageVisibleSecurityState|null = null;
  #summaryText = '';
  #explanations: Array<Protocol.Security.SecurityStateExplanation|SecurityStyleExplanation>|null = null;
  #securityState: Protocol.Security.SecurityState|null = null;
  #filterRequestCounts: ReadonlyMap<string, number> = new Map();

  readonly #showCertificateViewer = (certificate: string[]): void => {
    Host.InspectorFrontendHost.InspectorFrontendHostInstance.showCertificateViewer(certificate);
  };

  readonly #showNetworkFilter = (filterKey: string): void => {
    void Common.Revealer.reveal(NetworkForward.UIFilter.UIRequestFilter.filters(
        [{filterType: NetworkForward.UIFilter.FilterType.MixedContent, filterValue: filterKey}]));
  };

  constructor(element?: HTMLElement, view: SecurityMainViewFunction = DEFAULT_SECURITY_MAIN_VIEW) {
    super(element);
    this.#view = view;
    this.setMinimumSize(200, 100);
  }

  override wasShown(): void {
    super.wasShown();
    this.requestUpdate();
  }

  override performUpdate(): void {
    const mainExplanations: SecurityMainViewExplanation[] = [];
    const extraExplanations: SecurityMainViewExplanation[] = [];

    if (this.#explanations) {
      for (const explanation of this.#explanations) {
        if (explanation.securityState === Protocol.Security.SecurityState.Info) {
          extraExplanations.push({
            securityState: explanation.securityState,
            title: explanation.title,
            summary: explanation.summary,
            description: explanation.description,
            certificate: explanation.certificate ?? [],
            recommendations: explanation.recommendations,
          });
        } else {
          let mixedContent: {filterKey: string, count: number}|undefined;
          switch (explanation.mixedContentType) {
            case Protocol.Security.MixedContentType.Blockable: {
              const filterKey = NetworkForward.UIFilter.MixedContentFilterValues.BLOCK_OVERRIDDEN;
              mixedContent = {filterKey, count: this.#filterRequestCounts.get(filterKey) ?? 0};
              break;
            }
            case Protocol.Security.MixedContentType.OptionallyBlockable: {
              const filterKey = NetworkForward.UIFilter.MixedContentFilterValues.DISPLAYED;
              mixedContent = {filterKey, count: this.#filterRequestCounts.get(filterKey) ?? 0};
              break;
            }
            default:
              break;
          }
          mainExplanations.push({
            securityState: explanation.securityState,
            title: explanation.title,
            summary: explanation.summary,
            description: explanation.description,
            certificate: explanation.certificate ?? [],
            recommendations: explanation.recommendations,
            mixedContent,
          });
        }
      }
    }

    const blockedCount = this.#filterRequestCounts.get(NetworkForward.UIFilter.MixedContentFilterValues.BLOCKED) ?? 0;
    if (blockedCount > 0) {
      mainExplanations.push({
        securityState: Protocol.Security.SecurityState.Info,
        summary: i18nString(UIStrings.blockedMixedContent),
        description: i18nString(UIStrings.yourPageRequestedNonsecure),
        certificate: [],
        mixedContent: {
          filterKey: NetworkForward.UIFilter.MixedContentFilterValues.BLOCKED,
          count: blockedCount,
        },
      });
    }

    this.#view(
        {
          securityState: this.#securityState,
          summaryText: this.#summaryText,
          mainExplanations,
          extraExplanations,
          onShowCertificateViewer: this.#showCertificateViewer,
          onShowNetworkFilter: this.#showNetworkFilter,
        },
        undefined,
        this.contentElement,
    );
  }

  set filterRequestCounts(filterRequestCounts: ReadonlyMap<string, number>) {
    if (this.#filterRequestCounts === filterRequestCounts) {
      return;
    }
    this.#filterRequestCounts = filterRequestCounts;
    this.requestUpdate();
  }

  get filterRequestCounts(): ReadonlyMap<string, number> {
    return this.#filterRequestCounts;
  }

  set visibleSecurityState(visibleSecurityState: PageVisibleSecurityState|null) {
    if (this.#visibleSecurityState === visibleSecurityState) {
      return;
    }
    this.#visibleSecurityState = visibleSecurityState;
    if (visibleSecurityState) {
      this.#securityState = visibleSecurityState.securityState;
      const {summary, explanations} = this.#getSecuritySummaryAndExplanations(visibleSecurityState);
      this.#summaryText = summary || SummaryMessages[this.#securityState]();
      this.#explanations = this.#orderExplanations(explanations);
    } else {
      this.#securityState = null;
      this.#summaryText = '';
      this.#explanations = null;
    }
    this.requestUpdate();
  }

  get visibleSecurityState(): PageVisibleSecurityState|null {
    return this.#visibleSecurityState;
  }

  #getSecuritySummaryAndExplanations(visibleSecurityState: PageVisibleSecurityState):
      {summary: (string|undefined), explanations: SecurityStyleExplanation[]} {
    const {securityState, securityStateIssueIds} = visibleSecurityState;
    let summary;
    const explanations: SecurityStyleExplanation[] = [];
    summary = this.#explainSafetyTipSecurity(visibleSecurityState, summary, explanations);
    if (securityStateIssueIds.includes('malicious-content')) {
      summary = i18nString(UIStrings.thisPageIsDangerousFlaggedBy);
      // Always insert SafeBrowsing explanation at the front.
      explanations.unshift(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Insecure, undefined, i18nString(UIStrings.flaggedByGoogleSafeBrowsing),
          i18nString(UIStrings.toCheckThisPagesStatusVisit)));
    } else if (
        securityStateIssueIds.includes('is-error-page') &&
        (visibleSecurityState.certificateSecurityState?.certificateNetworkError === null)) {
      summary = i18nString(UIStrings.thisIsAnErrorPage);
      // In the case of a non cert error page, we usually don't have a
      // certificate, connection, or content that needs to be explained, e.g. in
      // the case of a net error, so we can early return.
      return {summary, explanations};
    } else if (
        securityState === Protocol.Security.SecurityState.InsecureBroken &&
        securityStateIssueIds.includes('scheme-is-not-cryptographic')) {
      summary = summary || i18nString(UIStrings.thisPageIsInsecureUnencrypted);
    }

    if (securityStateIssueIds.includes('scheme-is-not-cryptographic')) {
      if (securityState === Protocol.Security.SecurityState.Neutral &&
          !securityStateIssueIds.includes('insecure-origin')) {
        summary = i18nString(UIStrings.thisPageHasANonhttpsSecureOrigin);
      }
      return {summary, explanations};
    }

    this.#explainCertificateSecurity(visibleSecurityState, explanations);
    this.#explainConnectionSecurity(visibleSecurityState, explanations);
    this.#explainContentSecurity(visibleSecurityState, explanations);
    return {summary, explanations};
  }

  #explainSafetyTipSecurity(visibleSecurityState: PageVisibleSecurityState, summary: string|undefined,
                            explanations: SecurityStyleExplanation[]): string|undefined {
    const {securityStateIssueIds, safetyTipInfo} = visibleSecurityState;
    const currentExplanations = [];

    if (securityStateIssueIds.includes('bad_reputation')) {
      const formatedDescription = `${i18nString(UIStrings.chromeHasDeterminedThatThisSiteS)}\n\n${
          i18nString(UIStrings.ifYouBelieveThisIsShownIn)}`;
      currentExplanations.push({
        summary: i18nString(UIStrings.thisPageIsSuspicious),
        description: formatedDescription,
      });
    } else if (securityStateIssueIds.includes('lookalike') && safetyTipInfo?.safeUrl) {
      const hostname = new URL(safetyTipInfo.safeUrl).hostname;
      const hostnamePlaceholder = {PH1: hostname};
      const formattedDescriptionSafety =
          `${i18nString(UIStrings.thisSitesHostnameLooksSimilarToP, hostnamePlaceholder)}\n\n${
              i18nString(UIStrings.ifYouBelieveThisIsShownInErrorSafety)}`;
      currentExplanations.push(
          {summary: i18nString(UIStrings.possibleSpoofingUrl), description: formattedDescriptionSafety});
    }

    if (currentExplanations.length > 0) {
      // To avoid overwriting SafeBrowsing's title, set the main summary only if
      // it's empty. The title set here can be overridden by later checks (e.g.
      // bad HTTP).
      summary = summary || i18nString(UIStrings.thisPageIsSuspiciousFlaggedBy);
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Insecure, undefined, currentExplanations[0].summary,
          currentExplanations[0].description));
    }
    return summary;
  }

  #explainCertificateSecurity(visibleSecurityState: PageVisibleSecurityState,
                              explanations: SecurityStyleExplanation[]): void {
    const {certificateSecurityState, securityStateIssueIds} = visibleSecurityState;
    const title = i18nString(UIStrings.certificate);
    if (certificateSecurityState?.certificateHasSha1Signature) {
      const explanationSummary = i18nString(UIStrings.insecureSha);
      const description = i18nString(UIStrings.theCertificateChainForThisSite);
      if (certificateSecurityState.certificateHasWeakSignature) {
        explanations.push(new SecurityStyleExplanation(
            Protocol.Security.SecurityState.Insecure, title, explanationSummary, description,
            certificateSecurityState.certificate, Protocol.Security.MixedContentType.None));
      } else {
        explanations.push(new SecurityStyleExplanation(
            Protocol.Security.SecurityState.Neutral, title, explanationSummary, description,
            certificateSecurityState.certificate, Protocol.Security.MixedContentType.None));
      }
    }

    if (certificateSecurityState && securityStateIssueIds.includes('cert-missing-subject-alt-name')) {
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Insecure, title, i18nString(UIStrings.subjectAlternativeNameMissing),
          i18nString(UIStrings.theCertificateForThisSiteDoesNot), certificateSecurityState.certificate,
          Protocol.Security.MixedContentType.None));
    }

    if (certificateSecurityState && certificateSecurityState.certificateNetworkError !== null) {
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Insecure, title, i18nString(UIStrings.missing),
          i18nString(UIStrings.thisSiteIsMissingAValidTrusted, {PH1: certificateSecurityState.certificateNetworkError}),
          certificateSecurityState.certificate, Protocol.Security.MixedContentType.None));
    } else if (certificateSecurityState && !certificateSecurityState.certificateHasSha1Signature) {
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Secure, title, i18nString(UIStrings.validAndTrusted),
          i18nString(UIStrings.theConnectionToThisSiteIsUsingA, {PH1: certificateSecurityState.issuer}),
          certificateSecurityState.certificate, Protocol.Security.MixedContentType.None));
    }

    if (securityStateIssueIds.includes('pkp-bypassed')) {
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Info, title, i18nString(UIStrings.publickeypinningBypassed),
          i18nString(UIStrings.publickeypinningWasBypassedByA)));
    }

    if (certificateSecurityState?.isCertificateExpiringSoon()) {
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Info, undefined, i18nString(UIStrings.certificateExpiresSoon),
          i18nString(UIStrings.theCertificateForThisSiteExpires)));
    }
  }

  #explainConnectionSecurity(visibleSecurityState: PageVisibleSecurityState,
                             explanations: SecurityStyleExplanation[]): void {
    const certificateSecurityState = visibleSecurityState.certificateSecurityState;
    if (!certificateSecurityState) {
      return;
    }

    const title = i18nString(UIStrings.connection);
    if (certificateSecurityState.modernSSL) {
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Secure, title, i18nString(UIStrings.secureConnectionSettings),
          i18nString(UIStrings.theConnectionToThisSiteIs, {
            PH1: certificateSecurityState.protocol,
            PH2: certificateSecurityState.getKeyExchangeName(),
            PH3: certificateSecurityState.getCipherFullName(),
          })));
      return;
    }

    const recommendations = [];
    if (certificateSecurityState.obsoleteSslProtocol) {
      recommendations.push(i18nString(UIStrings.sIsObsoleteEnableTlsOrLater, {PH1: certificateSecurityState.protocol}));
    }
    if (certificateSecurityState.obsoleteSslKeyExchange) {
      recommendations.push(i18nString(UIStrings.rsaKeyExchangeIsObsoleteEnableAn));
    }
    if (certificateSecurityState.obsoleteSslCipher) {
      recommendations.push(
          i18nString(UIStrings.sIsObsoleteEnableAnAesgcmbased, {PH1: certificateSecurityState.cipher}));
    }
    if (certificateSecurityState.obsoleteSslSignature) {
      recommendations.push(i18nString(UIStrings.theServerSignatureUsesShaWhichIs));
    }

    explanations.push(new SecurityStyleExplanation(
        Protocol.Security.SecurityState.Info, title, i18nString(UIStrings.obsoleteConnectionSettings),
        i18nString(UIStrings.theConnectionToThisSiteIs, {
          PH1: certificateSecurityState.protocol,
          PH2: certificateSecurityState.getKeyExchangeName(),
          PH3: certificateSecurityState.getCipherFullName(),
        }),
        undefined, undefined, recommendations));
  }

  #explainContentSecurity(visibleSecurityState: PageVisibleSecurityState,
                          explanations: SecurityStyleExplanation[]): void {
    // Add the secure explanation unless there is an issue.
    let addSecureExplanation = true;
    const title = i18nString(UIStrings.resources);
    const securityStateIssueIds = visibleSecurityState.securityStateIssueIds;

    if (securityStateIssueIds.includes('ran-mixed-content')) {
      addSecureExplanation = false;
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Insecure, title, i18nString(UIStrings.activeMixedContent),
          i18nString(UIStrings.youHaveRecentlyAllowedNonsecure), [], Protocol.Security.MixedContentType.Blockable));
    }

    if (securityStateIssueIds.includes('displayed-mixed-content')) {
      addSecureExplanation = false;
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Neutral, title, i18nString(UIStrings.mixedContent),
          i18nString(UIStrings.thisPageIncludesHttpResources), [],
          Protocol.Security.MixedContentType.OptionallyBlockable));
    }

    if (securityStateIssueIds.includes('contained-mixed-form')) {
      addSecureExplanation = false;
      explanations.push(new SecurityStyleExplanation(
          Protocol.Security.SecurityState.Neutral, title, i18nString(UIStrings.nonsecureForm),
          i18nString(UIStrings.thisPageIncludesAFormWithA)));
    }

    if (visibleSecurityState.certificateSecurityState?.certificateNetworkError === null) {
      if (securityStateIssueIds.includes('ran-content-with-cert-error')) {
        addSecureExplanation = false;
        explanations.push(new SecurityStyleExplanation(
            Protocol.Security.SecurityState.Insecure, title, i18nString(UIStrings.activeContentWithCertificate),
            i18nString(UIStrings.youHaveRecentlyAllowedContent)));
      }

      if (securityStateIssueIds.includes('displayed-content-with-cert-errors')) {
        addSecureExplanation = false;
        explanations.push(new SecurityStyleExplanation(
            Protocol.Security.SecurityState.Neutral, title, i18nString(UIStrings.contentWithCertificateErrors),
            i18nString(UIStrings.thisPageIncludesResourcesThat)));
      }
    }

    if (addSecureExplanation) {
      if (!securityStateIssueIds.includes('scheme-is-not-cryptographic')) {
        explanations.push(new SecurityStyleExplanation(
            Protocol.Security.SecurityState.Secure, title, i18nString(UIStrings.allServedSecurely),
            i18nString(UIStrings.allResourcesOnThisPageAreServed)));
      }
    }
  }

  #orderExplanations(explanations: SecurityStyleExplanation[]): SecurityStyleExplanation[] {
    if (explanations.length === 0) {
      return explanations;
    }
    const securityStateOrder = [
      Protocol.Security.SecurityState.Insecure,
      Protocol.Security.SecurityState.Neutral,
      Protocol.Security.SecurityState.Secure,
      Protocol.Security.SecurityState.Info,
    ];
    const orderedExplanations = [];
    for (const securityState of securityStateOrder) {
      orderedExplanations.push(...explanations.filter(explanation => explanation.securityState === securityState));
    }
    return orderedExplanations;
  }
}

const SAN_NUM_SHOWN_WHEN_TRUNCATED = 2;

function isSanListTruncatable(sanList: string[]): boolean {
  return sanList.length > SAN_NUM_SHOWN_WHEN_TRUNCATED + 1;
}

function renderSan(sanList: string[], isSanListTruncated: boolean, onToggleTruncation: () => void): TemplateResult {
  if (sanList.length === 0) {
    return html`<div class="san empty-san">${i18nString(UIStrings.na)}</div>`;
  }

  const isTruncatable = isSanListTruncatable(sanList);
  const toggleButtonText =
      isSanListTruncated ? i18nString(UIStrings.showMoreSTotal, {PH1: sanList.length}) : i18nString(UIStrings.showLess);

  // clang-format off
  return html`
    <div class=${Directives.classMap({ san: true, 'truncated-san': isSanListTruncated })}>
      ${sanList.map((san, index) => {
        return html`
          <span class=${Directives.classMap({
            'san-entry': true,
            'truncated-entry': isTruncatable && index >= SAN_NUM_SHOWN_WHEN_TRUNCATED,
          })}>${san}</span>`;
      })}
      ${isTruncatable ? html`
        <devtools-button
          .variant=${Buttons.Button.Variant.OUTLINED}
          .accessibleLabel=${toggleButtonText}
          .accessibleExpanded=${!isSanListTruncated}
          .jslogContext=${'security.toggle-san-truncation'}
          @click=${onToggleTruncation}>${toggleButtonText}
        </devtools-button>` : nothing}
    </div>`;
  // clang-format on
}

interface DetailsTableRow {
  key?: string;
  value: string|TemplateResult;
}

function renderDetailsTable(rows: DetailsTableRow[], additionalClasses: Directives.ClassInfo = {}): TemplateResult {
  // clang-format off
  return html`
    <table class=${Directives.classMap({'details-table': true, ...additionalClasses})}>
      ${rows.map(row => html`
        <tr class="details-table-row">
          <td>${row.key ?? nothing}</td>
          <td>${row.value}</td>
        </tr>`)}
    </table>`;
  // clang-format on
}

function formatKeyExchange(securityDetails: Protocol.Network.SecurityDetails): string|null {
  // A TLS connection negotiates a cipher suite and, when doing an ephemeral
  // ECDH key exchange, a "named group". In TLS 1.2, the cipher suite is
  // named like TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256. The DevTools protocol
  // tried to decompose this name and calls the "ECDHE_RSA" portion the
  // "keyExchange", because it determined the rough shape of the key
  // exchange portion of the handshake. (A keyExchange of "RSA" meant a very
  // different handshake set.) But ECDHE_RSA was still parameterized by a
  // named group (e.g. X25519), which the DevTools protocol exposes as
  // "keyExchangeGroup".
  //
  // Then, starting TLS 1.3, the cipher suites are named like
  // TLS_AES_128_GCM_SHA256. The handshake shape is implicit in the
  // protocol. keyExchange is empty and we only have keyExchangeGroup.
  //
  // "Key exchange group" isn't common terminology and, in TLS 1.3,
  // something like "X25519" is better labelled as "key exchange" than "key
  // exchange group" anyway. So combine the two fields when displaying in
  // the UI.
  if (securityDetails.keyExchange && securityDetails.keyExchangeGroup) {
    return securityDetails.keyExchange + ' with ' + securityDetails.keyExchangeGroup;
  }
  return securityDetails.keyExchange || securityDetails.keyExchangeGroup || null;
}

function buildConnectionDetailsRows(securityDetails: Protocol.Network.SecurityDetails): DetailsTableRow[] {
  const rows: DetailsTableRow[] = [{key: i18nString(UIStrings.protocol), value: securityDetails.protocol}];

  const keyExchange = formatKeyExchange(securityDetails);
  if (keyExchange) {
    rows.push({key: i18nString(UIStrings.keyExchange), value: keyExchange});
  }

  if (securityDetails.serverSignatureAlgorithm) {
    // See https://www.iana.org/assignments/tls-parameters/tls-parameters.xhtml#tls-signaturescheme
    let sigString = SignatureSchemeStrings.get(securityDetails.serverSignatureAlgorithm);
    sigString ??= i18nString(UIStrings.unknownField) + ' (' + securityDetails.serverSignatureAlgorithm + ')';
    rows.push({key: i18nString(UIStrings.serverSignature), value: sigString});
  }

  rows.push({
    key: i18nString(UIStrings.cipher),
    value: securityDetails.cipher + (securityDetails.mac ? ' with ' + securityDetails.mac : ''),
  });

  if (securityDetails.encryptedClientHello) {
    rows.push({key: i18nString(UIStrings.encryptedClientHello), value: i18nString(UIStrings.enabled)});
  }

  return rows;
}

function renderConnectionSection(securityDetails: Protocol.Network.SecurityDetails): TemplateResult {
  const rows = buildConnectionDetailsRows(securityDetails);

  // clang-format off
  return html`
    <div class="origin-view-section-title" role="heading" aria-level="2">${i18nString(UIStrings.connection)}</div>
    ${renderDetailsTable(rows)}`;
  // clang-format on
}

